/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getBand = require( './band/get.js' );
var setBand = require( './band/set.js' );

var getColor = require( './color/get.js' );
var setColor = require( './color/set.js' );

var getExponent = require( './exponent/get.js' );
var setExponent = require( './exponent/set.js' );

var getField = require( './field/get.js' );
var setField = require( './field/set.js' );

var getMult = require( './mult/get.js' );
var setMult = require( './mult/set.js' );

var getOffset = require( './offset/get.js' );
var setOffset = require( './offset/set.js' );

var getProperties = require( './properties/get.js' );

var getRound = require( './round/get.js' );
var setRound = require( './round/set.js' );

var getScale = require( './scale/get.js' );
var setScale = require( './scale/set.js' );
var getSignal = require( './signal/get.js' );
var setSignal = require( './signal/set.js' );

var getValue = require( './value/get.js' );
var setValue = require( './value/set.js' );


// VARIABLES //

var debug = logger( 'vega:value:main' );


// MAIN //

/**
* Value constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {number} [options.band] - band width of a scale multiplication factor
* @param {Object} [options.color] - color value specifying per-channel references
* @param {(number|Value)} [options.exponent] - scale exponent modifier
* @param {(string|FieldDescriptor)} [options.field] - data field name or descriptor
* @param {(number|Value)} [options.mult] - scale multiplier modifier
* @param {(number|Value)} [options.offset] - scale additive offset
* @param {boolean} [options.round] - boolean indicating whether to round a value after scale transformations
* @param {(string|FieldDescriptor)} [options.scale] - name of scale transform to apply or a field descriptor
* @param {string} [options.signal] - signal name or expression
* @param {*} [options.value] - constant value
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Value} value instance
*
* @example
* var value = new Value();
* // returns <Value>
*/
function Value( options ) {
	var nargs;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Value ) ) {
		if ( nargs ) {
			return new Value( options );
		}
		return new Value();
	}
	EventEmitter.call( this );

	// Set internal properties to undefined (no defaults per Vega spec)...
	for ( i = 0; i < properties.length; i++ ) {
		this[ '_'+properties[ i ] ] = void 0;
	}
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Value, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Value
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Value, 'name', 'Value' );

/**
* Returns a boolean indicating if a value is a value instance.
*
* ## Notes
*
* -   This method is intended for use within this class only and is present in order to avoid a circular dependency on `@stdlib/plot/vega/base/assert/is-value-reference`. The method should use the same brand checks.
*
* @private
* @name _isValue
* @memberof Value.prototype
* @param {*} value - value to test
* @returns {boolean} boolean indicating if a value is a value instance
*/
setNonEnumerableReadOnly( Value.prototype, '_isValue', function isValue( value ) {
	return (
		value instanceof this ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			(
				hasProp( value, 'signal' ) ||
				hasProp( value, 'color' ) ||
				hasProp( value, 'field' ) ||
				hasProp( value, 'value' )
			)
		)
	);
});

/**
* Band width of a scale multiplication factor.
*
* @name band
* @memberof Value.prototype
* @type {(number|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'band': 0.5
* });
*
* var v = value.band;
* // returns 0.5
*/
setReadWriteAccessor( Value.prototype, 'band', getBand, setBand );

/**
* Color value specifying per-channel references.
*
* @name color
* @memberof Value.prototype
* @type {(Object|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'color': { 'r': { 'value': 255 }, 'g': { 'value': 0 }, 'b': { 'value': 0 } }
* });
*
* var c = value.color;
* // returns { 'r': { 'value': 255 }, 'g': { 'value': 0 }, 'b': { 'value': 0 } }
*/
setReadWriteAccessor( Value.prototype, 'color', getColor, setColor );

/**
* Scale exponent modifier.
*
* @name exponent
* @memberof Value.prototype
* @type {(number|Value|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'exponent': 2
* });
*
* var v = value.exponent;
* // returns 2
*/
setReadWriteAccessor( Value.prototype, 'exponent', getExponent, setExponent );

/**
* Data field name or descriptor.
*
* @name field
* @memberof Value.prototype
* @type {(string|Object|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'field': 'price'
* });
*
* var v = value.field;
* // returns 'price'
*/
setReadWriteAccessor( Value.prototype, 'field', getField, setField );

/**
* Scale multiplier modifier.
*
* @name mult
* @memberof Value.prototype
* @type {(number|Value|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'mult': 2
* });
*
* var v = value.mult;
* // returns 2
*/
setReadWriteAccessor( Value.prototype, 'mult', getMult, setMult );

/**
* Scale additive offset.
*
* @name offset
* @memberof Value.prototype
* @type {(number|Value|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'offset': 5
* });
*
* var v = value.offset;
* // returns 5
*/
setReadWriteAccessor( Value.prototype, 'offset', getOffset, setOffset );

/**
* Value properties.
*
* @name properties
* @memberof Value.prototype
* @type {Array<string>}
*
* @example
* var value = new Value();
*
* var v = value.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Value.prototype, 'properties', getProperties );

/**
* Boolean indicating whether to round a value after scale transformations.
*
* @name round
* @memberof Value.prototype
* @type {(boolean|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'round': true
* });
*
* var v = value.round;
* // returns true
*/
setReadWriteAccessor( Value.prototype, 'round', getRound, setRound );

/**
* Name of a scale transform to apply or a field descriptor.
*
* @name scale
* @memberof Value.prototype
* @type {(string|FieldDescriptor|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'scale': 'xScale'
* });
*
* var v = value.scale;
* // returns 'xScale'
*/
setReadWriteAccessor( Value.prototype, 'scale', getScale, setScale );

/**
* Signal name or expression.
*
* @name signal
* @memberof Value.prototype
* @type {(string|void)}
* @default undefined
*
* @example
* var value = new Value({
*     'signal': 'width'
* });
*
* var v = value.signal;
* // returns 'width'
*/
setReadWriteAccessor( Value.prototype, 'signal', getSignal, setSignal );

/**
* Constant value.
*
* @name value
* @memberof Value.prototype
* @type {*}
* @default undefined
*
* @example
* var value = new Value({
*     'value': 5
* });
*
* var v = value.value;
* // returns 5
*/
setReadWriteAccessor( Value.prototype, 'value', getValue, setValue );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Value.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var value = new Value({
*     'value': 5
* });
*
* var json = value.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Value.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Value;
